using UnityEngine;using UnityEditor;using System.Collections;using System.IO;using System.Linq;using System.Reflection;
[InitializeOnLoad]public static class DirectCrankCheckTemp{static DirectCrankCheckTemp(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&File.Exists("Temp/DirectCrankCheckRun")){File.Delete("Temp/DirectCrankCheckRun");new GameObject("Direct crank check").AddComponent<DirectCrankCheckRunner>();}if(s==PlayModeStateChange.EnteredEditMode&&File.Exists("Temp/DirectCrankSaveBackup")){var b=File.ReadAllText("Temp/DirectCrankSaveBackup");if(b=="NONE")PlayerPrefs.DeleteKey("checkpoint.v1");else PlayerPrefs.SetString("checkpoint.v1",b);PlayerPrefs.Save();File.Delete("Temp/DirectCrankSaveBackup");}};EditorApplication.delayCall+=()=>{if(!File.Exists("Temp/DirectCrankCheckRun"))return;File.WriteAllText("Temp/DirectCrankSaveBackup",PlayerPrefs.HasKey("checkpoint.v1")?PlayerPrefs.GetString("checkpoint.v1"):"NONE");EditorApplication.isPlaying=true;};}}
public class DirectCrankCheckRunner:MonoBehaviour{
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;T Get<T>(object o,string n)=>(T)o.GetType().GetField(n,Flags).GetValue(o);void Set(object o,string n,object v)=>o.GetType().GetField(n,Flags).SetValue(o,v);void Log(string s)=>File.AppendAllText("Temp/DirectCrankResult.txt",s+"\n");
 float Angle(Vector2 p,Vector2 c)=>Mathf.Atan2(p.y-c.y,p.x-c.x)*Mathf.Rad2Deg;
 IEnumerator Start(){yield return new WaitForSeconds(3);File.WriteAllText("Temp/DirectCrankResult.txt","");foreach(var e in Object.FindObjectsOfType<ElfEncounter>())e.enabled=false;foreach(var e in Object.FindObjectsOfType<FaceMonsterEncounter>())e.enabled=false;var jack=Object.FindObjectOfType<JackInTheBoxInteraction>();var player=Object.FindObjectOfType<UnityStandardAssets.Characters.FirstPerson.FirstPersonController>();foreach(var fx in Camera.main.GetComponents<MonoBehaviour>())fx.enabled=false;RenderSettings.fog=false;Set(jack,"music",AudioClip.Create("Test winding",441000,1,44100,false));jack.Interact();yield return new WaitForSeconds(.7f);var crank=Get<Transform>(jack,"crank");var grip=Get<Transform>(jack,"crankGrip");var camera=Camera.main;Vector2 centre=camera.WorldToScreenPoint(crank.position);Vector2 start=camera.WorldToScreenPoint(grip.position);Log("Outside click rejected="+!jack.BeginCrankDrag(Vector2.one*5));Log("Handle grab accepted="+jack.BeginCrankDrag(start));Vector2 offset=start-centre;Vector2 target=centre+new Vector2(-offset.y,offset.x);jack.DragCrank(target,Time.deltaTime);bool audio=Get<AudioSource>(jack,"musicSource").isPlaying;yield return null;yield return new WaitForEndOfFrame();Vector2 actual=camera.WorldToScreenPoint(grip.position);Log("Physical handle follows 90 degree drag; angle error="+Mathf.Abs(Mathf.DeltaAngle(Angle(target,centre),Angle(actual,centre))));bool played=audio;for(int i=0;i<18;i++){centre=camera.WorldToScreenPoint(crank.position);start=camera.WorldToScreenPoint(grip.position);jack.BeginCrankDrag(start);offset=start-centre;float a=15*Mathf.Deg2Rad;target=centre+new Vector2(offset.x*Mathf.Cos(a)-offset.y*Mathf.Sin(a),offset.x*Mathf.Sin(a)+offset.y*Mathf.Cos(a));jack.DragCrank(target,Time.deltaTime);played|=Get<AudioSource>(jack,"musicSource").isPlaying;yield return null;}Log("Direct dragging advances winding="+(jack.WindingProgress>0)+" music plays="+played);jack.EndCrankDrag();yield return null;Log("Release pauses music="+!Get<AudioSource>(jack,"musicSource").isPlaying);Log("Old UI wheel absent="+(Get<GameObject>(jack,"windingUI").transform.Find("Winding Controls/Wheel Background")==null));ScreenCapture.CaptureScreenshot("Temp/DirectCrankPreview.png");yield return new WaitForSeconds(.1f);jack.PutDown();yield return new WaitForSeconds(.65f);Log("Put down restores control="+player.enabled);EditorApplication.isPlaying=false;}
}
